import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/replies-stagers-20261019';await fs.mkdir(dir,{recursive:true});
async function all(t,q){let a=[];for(let offset=0;;offset+=1000){const p=await db(t,{...q,order:'id.asc',offset:String(offset),limit:'1000'});a.push(...p);if(p.length<1000)return a;}}
const results=await Promise.allSettled([all('market_touches',{direction:'eq.inbound',created_at:'gte.2026-10-19T17:45:00Z'}),all('market_contacts',{or:'(name.ilike.*stag*,company.ilike.*stag*,industry.ilike.*stag*,category.ilike.*stag*,name.ilike.*tasha*,company.ilike.*interior*,industry.ilike.*interior*,category.ilike.*interior*)'})]);for(const r of results)if(r.status==='rejected')throw r.reason;const recent=results[0].value,stagers=results[1].value;const ids=[...new Set([...recent.map(t=>t.contact_id),...stagers.map(c=>c.id)])];const rows=[];for(const id of ids){const[c]=await db('market_contacts',{id:'eq.'+id});const thread=await db('market_touches',{contact_id:'eq.'+id,order:'created_at.asc,id.asc',limit:'1000'});if(thread.length===1000)throw Error('paginate');rows.push({contact:c,thread,recent:recent.some(t=>t.contact_id===id),stager:stagers.some(t=>t.id===id)});}await fs.writeFile(dir+'/review.json',JSON.stringify({at:new Date().toISOString(),rows},null,2));console.log(JSON.stringify({at:new Date().toISOString(),recent:recent.length,stagers:stagers.length,threads:rows.length}));
